SELECT 
FROM insight_result
WHERE period = #{period}
  AND metric_version = #{metricVersion}
  AND prompt_version = #{promptVersion}
  AND insight_type = #{insightType}
  AND card_id = #{cardId}

SELECT 
FROM insight_result
WHERE insight_type = 'scenario'
  AND period = #{period}
  AND metric_version = #{metricVersion}
  AND prompt_version = #{promptVersion}
  AND status = 'ready'
ORDER BY updated_at DESC
LIMIT 50

SELECT 
FROM insight_result
WHERE period = #{period}
  AND metric_version = #{metricVersion}
  AND prompt_version = #{promptVersion}
  AND insight_type = #{insightType}
